"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["74795"],{23842(e){e.exports=JSON.parse('{"id":"F094","slug":"sahm-rule-indicator","name":"Sahm Rule Recession Indicator","subject":"Economics for Finance","section":"Markets and the Economy","topic":"Recessions and their warning signs","level":"Intermediate","aliases":["recessions and their warning signs","unemployment trigger","yield curve inversion"],"formula":{"latex":"S=\\\\bar{u}_{3m}-\\\\min_{12m}\\\\bar{u}_{3m},\\\\quad \\\\text{Signal if }S\\\\ge0.5","also":[],"text":"Sahm indicator = latest 3-month average unemployment rate - the lowest 3-month average of the previous 12 months. A reading of 0.5 percentage points or more has signaled the start of past US recessions. Yield curve spread = 10-year yield - 3-month yield (negative means inverted)"},"symbols":[{"symbol":"u","meaning":"Monthly unemployment rate","unit":"percent"},{"symbol":"3m average","meaning":"Average of the latest three monthly readings","unit":"percent"},{"symbol":"Spread","meaning":"Long yield minus short yield","unit":"percent"}],"when_to_use":"Use it as one warning sign, alongside an inverted yield curve and falling surveys. The Sahm rule picks up a quick rise in unemployment, which has historically happened early in recessions. Neither signal is a forecast: they have had false alarms and different lags, and the rule was fitted to US data. Enter at least 15 monthly readings, oldest first.","worked_example":{"problem":"Sixteen months of unemployment readings are in the calculator. The 10-year yield is 3.9% and the 3-month yield is 4.5%.","inputs":{"u":[3.6,3.5,3.6,3.7,3.7,3.7,3.8,3.8,3.9,4,4.1,4.2,4.3,4.4,4.5,4.6],"y10":3.9,"y3m":4.5},"steps":[{"label":"Rolling 3-month averages","working":null,"value":"3.57%, 3.60%, 3.67%, 3.70%, 3.73%, 3.77%, 3.83%, 3.90%, 4.00%, 4.10%, 4.20%, 4.30%, 4.40%, 4.50%"},{"label":"Latest 3-month average","working":null,"value":"4.50%"},{"label":"Lowest 3-month average in the prior 12 months","working":"min([0.0356667, 0.036, 0.0366667, 0.037, 0.0373333, 0.0376667, 0.0383333, 0.039, 0.04, 0.041, 0.042, 0.043, 0.044, 0.045][-13:-1])","value":"3.60%"},{"label":"Sahm indicator = latest - prior low","working":"0.045-0.036","value":"0.90%"},{"label":"Sahm signal (1 = yes, 0 = no)","working":"1 if 0.009>=0.005 else 0","value":"1"},{"label":"Yield curve spread = 10-year - 3-month","working":"0.039-0.045","value":"-0.60%"},{"label":"Curve inverted (1 = yes, 0 = no)","working":"1 if -0.006<0 else 0","value":"1"}],"answer":"The latest 3-month average is 4.50% against a prior 12-month low of 3.60%, so the indicator is 0.90% points. The yield curve spread is -0.60%. Signal flags: Sahm 1 and curve inverted 1 (1 = yes, 0 = no)."},"calculator":{"available":true,"inputs":[{"id":"u","label":"Monthly unemployment rate, oldest first","unit":"%","type":"list","default":[3.6,3.5,3.6,3.7,3.7,3.7,3.8,3.8,3.9,4,4.1,4.2,4.3,4.4,4.5,4.6],"hint":""},{"id":"y10","label":"10-year yield","unit":"%","type":"number","default":3.9,"hint":""},{"id":"y3m","label":"3-month yield","unit":"%","type":"number","default":4.5,"hint":""}],"checks":[{"expr":"count(u)>=15","message":"Enter at least 15 monthly readings."}],"steps":[{"id":"rm","label":"Rolling 3-month averages","expr":"rollmean(u, 3)","format":"list2pct"},{"id":"now","label":"Latest 3-month average","expr":"last(rm,1)[0]","format":"pct2"},{"id":"low","label":"Lowest 3-month average in the prior 12 months","expr":"min(rm[-13:-1])","format":"pct2"},{"id":"sahm","label":"Sahm indicator = latest - prior low","expr":"now-low","format":"pct2"},{"id":"sig_","label":"Sahm signal (1 = yes, 0 = no)","expr":"1 if sahm>=0.005 else 0","format":"num0"},{"id":"sp","label":"Yield curve spread = 10-year - 3-month","expr":"y10-y3m","format":"pct2"},{"id":"inv_","label":"Curve inverted (1 = yes, 0 = no)","expr":"1 if sp<0 else 0","format":"num0"}],"results":["sahm","sig_","sp","inv_"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"now":0.045,"low":3.6000000000000004e-2,"sahm":0.009,"sig_":1,"sp":-0.006,"inv_":1}},"finder":{"finds":"Two classic recession warning signals","needs":"A run of monthly unemployment rates and two yields"},"related":[{"slug":"labor-market-rates","name":"Unemployment, Participation and Employment Rates"},{"slug":"okun-law","name":"Okun\'s Law"},{"slug":"yield-curve-slope","name":"Yield Curve Slope and Curvature"}],"related_ids":["F084","F083","F291"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>S</mi><mo>=</mo><msub><mover accent=\\"true\\"><mi>u</mi><mo>\u02C9</mo></mover><mrow><mn>3</mn><mi>m</mi></mrow></msub><mo>\u2212</mo><munder><mrow><mi>min</mi><mo>\u2061</mo></mrow><mrow><mn>12</mn><mi>m</mi></mrow></munder><msub><mover accent=\\"true\\"><mi>u</mi><mo>\u02C9</mo></mover><mrow><mn>3</mn><mi>m</mi></mrow></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Signal\xa0if\xa0</mtext><mi>S</mi><mo>\u2265</mo><mn>0.5</mn></mrow><annotation encoding=\\"application/x-tex\\">S=\\\\bar{u}_{3m}-\\\\min_{12m}\\\\bar{u}_{3m},\\\\quad \\\\text{Signal if }S\\\\ge0.5</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"rule-of-72","name":"Rule of 72"},"next":{"slug":"sample-size-mean","name":"Sample Size for Estimating a Mean"},"lesson":null,"total":522}')}}]);